use crate::util;
use serde_json::{json,Value};
use tauri::AppHandle;
pub fn init(app:&AppHandle){if util::setting("supportWatch")==true{watch(app.clone());}}
pub fn secret(name:&str)->Option<String>{std::fs::read_to_string(util::data_dir().join(".env")).ok()?.lines().find_map(|l|l.strip_prefix(&format!("{name}=")).and_then(|v|serde_json::from_str(v).ok()))}
pub fn save_secret(name:&str,value:&str)->Result<(),String>{let _env=util::ENV.lock().unwrap();if !name.bytes().all(|b|b.is_ascii_uppercase()||b==b'_'){return Err("Неверный ключ".into());}let file=util::data_dir().join(".env");let old=std::fs::read_to_string(&file).unwrap_or_default();let mut lines:Vec<_>=old.lines().filter(|l|!l.starts_with(&format!("{name}="))).map(str::to_string).collect();lines.push(format!("{name}={}",json!(value)));util::atomic_write(&file,(lines.join("\n")+"\n").as_bytes())}
async fn remote(command:&str)->Result<Value,String>{let host=secret("PULT_SSH_HOST").filter(|s|!s.is_empty()&&!s.starts_with('-')).ok_or("Не настроен SSH host")?;let key=secret("PULT_SSH_KEY").unwrap_or_else(||util::home().join(".ssh/id_ed25519").to_string_lossy().to_string());let mut cmd=util::command(util::find_bin("ssh").ok_or("Не установлен OpenSSH Client")?);cmd.args(["-i",&key,"-o","BatchMode=yes","-o","ConnectTimeout=10","-o","ServerAliveInterval=10","-o","ServerAliveCountMax=2","--",&host,command]).kill_on_drop(true);let result=tokio::time::timeout(std::time::Duration::from_secs(45),cmd.output()).await.map_err(|_|"SSH timeout")?.map_err(|_|"Не удалось запустить SSH")?;if !result.status.success(){return Err("SSH не выполнил запрос".into());}let output=String::from_utf8_lossy(&result.stdout);if output.len()>2_000_000{return Err("Ответ сервера слишком большой".into());}Ok(serde_json::from_str(&output).unwrap_or_else(|_|json!(output.trim())))}
pub async fn call(app:&AppHandle,method:&str,a:Value)->Result<Value,String>{match method{
"watch"=>{util::set_setting("supportWatch",json!(true));watch(app.clone());Ok(Value::Null)},
"stopWatch"=>{WATCH.fetch_add(1,std::sync::atomic::Ordering::SeqCst);util::set_setting("supportWatch",json!(false));Ok(Value::Null)},
"proxyConfigure"=>{let link=a["link"].as_str().ok_or("Нет VLESS ссылки")?;proxy_config(link)?;save_secret("PULT_VLESS",link)?;save_secret("PULT_XRAY",a["executable"].as_str().ok_or("Нет пути xray")?)?;Ok(Value::Null)},
"proxyStart"=>proxy_start().await,
"proxyStop"=>{if let Some(mut child)=PROXY.lock().unwrap().take(){let _=child.start_kill();}Ok(Value::Null)},
"proxyState"=>Ok(json!({"running":!proxy_env().is_empty()})),
"configure"=>{for name in ["PULT_SSH_HOST","PULT_SSH_KEY"]{if let Some(value)=a[name].as_str(){save_secret(name,value)?;}}Ok(json!({"ok":true}))},"state"=>Ok(json!({"configured":secret("PULT_SSH_HOST").is_some()})),"status"=>remote("python3 /usr/local/lib/coder-chat/bot_status.py").await,"changes"=>remote("python3 /usr/local/lib/coder-chat/deploy_ctl.py changes").await,"deploy"=>remote("python3 /usr/local/lib/coder-chat/deploy_ctl.py start").await,"deployLog"=>{let id=a["id"].as_str().filter(|s|!s.is_empty()&&s.len()<100&&s.bytes().all(|b|b.is_ascii_alphanumeric()||b==b'-'||b==b'_')).ok_or("Неверный ID выкладки")?;remote(&format!("python3 /usr/local/lib/coder-chat/deploy_ctl.py log {id}")).await},_=>Err("Неизвестный метод support".into())}}

static PROXY:std::sync::Mutex<Option<tokio::process::Child>>=std::sync::Mutex::new(None);
pub fn proxy_env()->Vec<(String,String)>{let mut proxy=PROXY.lock().unwrap();if proxy.as_mut().is_some_and(|p|p.try_wait().ok().flatten().is_none()){["HTTPS_PROXY","HTTP_PROXY","https_proxy","http_proxy"].into_iter().map(|k|(k.into(),"http://127.0.0.1:10809".into())).chain(std::iter::once(("NO_PROXY".into(),"127.0.0.1,localhost".into()))).collect()}else{vec![]}}
fn proxy_config(link:&str)->Result<Value,String>{let url=reqwest::Url::parse(link).map_err(|_|"Неверная VLESS ссылка")?;if url.scheme()!="vless"||uuid::Uuid::parse_str(url.username()).is_err()||url.host_str().is_none(){return Err("Нужна VLESS ссылка с UUID и host".into());}let q:std::collections::HashMap<_,_>=url.query_pairs().map(|(k,v)|(k.into_owned(),v.into_owned())).collect();let get=|k:&str,d:&str|q.get(k).cloned().unwrap_or_else(||d.into());let host=url.host_str().unwrap();let network=get("type","tcp");let security=get("security","none");if !["tcp","ws","grpc"].contains(&network.as_str())||!["none","tls","reality"].contains(&security.as_str()){return Err("Неподдерживаемый транспорт VLESS".into());}let mut stream=json!({"network":network,"security":security});if security=="reality"{stream["realitySettings"]=json!({"serverName":get("sni",""),"publicKey":get("pbk",""),"shortId":get("sid",""),"fingerprint":get("fp","chrome"),"spiderX":get("spx","")});}if security=="tls"{stream["tlsSettings"]=json!({"serverName":get("sni",host),"fingerprint":get("fp","chrome")});}if network=="ws"{stream["wsSettings"]=json!({"path":get("path","/"),"headers":{"Host":get("host",host)}});}if network=="grpc"{stream["grpcSettings"]=json!({"serviceName":get("serviceName","")});}let mut user=json!({"id":url.username(),"encryption":get("encryption","none")});if q.contains_key("flow"){user["flow"]=json!(get("flow",""));}Ok(json!({"log":{"loglevel":"none"},"inbounds":[{"listen":"127.0.0.1","port":10809,"protocol":"http"}],"outbounds":[{"protocol":"vless","settings":{"vnext":[{"address":host,"port":url.port().unwrap_or(443),"users":[user]}]},"streamSettings":stream}]}))}
async fn proxy_start()->Result<Value,String>{use tokio::io::AsyncWriteExt;let config=proxy_config(&secret("PULT_VLESS").ok_or("Нет VLESS ссылки")?)?;let binary=secret("PULT_XRAY").filter(|s|!s.is_empty()).ok_or("Выбери установленный xray.exe")?;if let Some(mut old)=PROXY.lock().unwrap().take(){let _=old.start_kill();}let mut cmd=util::command(binary);cmd.args(["run","-format","json","-c","stdin:"]).stdin(std::process::Stdio::piped()).stdout(std::process::Stdio::null()).stderr(std::process::Stdio::null()).kill_on_drop(true);let mut child=cmd.spawn().map_err(|_|"Не удалось запустить xray")?;let mut input=child.stdin.take().ok_or("Нет stdin xray")?;input.write_all(config.to_string().as_bytes()).await.map_err(|_|"Не удалось передать VLESS конфигурацию")?;drop(input);tokio::time::sleep(std::time::Duration::from_millis(500)).await;if child.try_wait().map_err(|_|"Ошибка xray")?.is_some(){return Err("xray завершился при запуске; проверь ссылку и порт 10809".into());}*PROXY.lock().unwrap()=Some(child);Ok(json!({"running":true}))}
#[cfg(test)]mod tests{use super::*;#[test]fn vless_config_stays_on_loopback(){let c=proxy_config("vless://b269989f-2a14-49ef-abf7-6d0f76b03962@example.test:443?security=tls&type=ws&path=%2Ftest").unwrap();assert_eq!(c["inbounds"][0]["listen"],"127.0.0.1");assert_eq!(c["outbounds"][0]["streamSettings"]["wsSettings"]["path"],"/test");assert!(proxy_config("https://example.test").is_err());}}

static WATCH:std::sync::atomic::AtomicU64=std::sync::atomic::AtomicU64::new(0);
fn watch(app:AppHandle){use std::sync::atomic::Ordering::SeqCst;use tauri::Emitter;let generation=WATCH.fetch_add(1,SeqCst)+1;tauri::async_runtime::spawn(async move{let mut seen:std::collections::HashSet<i64>=util::setting("supportSeenTrades").as_array().into_iter().flatten().filter_map(Value::as_i64).collect();let mut down=false;while WATCH.load(SeqCst)==generation{match remote("python3 /usr/local/lib/coder-chat/bot_status.py").await{Ok(status)=>{if WATCH.load(SeqCst)!=generation{break;}let now_down=status["service"]!="active";if now_down&&!down{let _=util::notify(&app,"Торговый бот","Служба не работает",false);let _=app.emit("support",json!({"alarm":true,"text":"Торговый бот: служба не работает"}));}down=now_down;let first=seen.is_empty();for row in status["last"].as_array().into_iter().flatten(){if let Some(id)=row["id"].as_i64(){if seen.insert(id)&&!first&&row["pnl_pct"].as_f64().unwrap_or(0.0)<=-40.0{let text=format!("Сделка #{id}: {}%",row["pnl_pct"]);let _=util::notify(&app,"Торговый бот",&text,false);let _=app.emit("support",json!({"alarm":true,"text":text}));}}}if seen.len()>500{let mut ids:Vec<_>=seen.iter().copied().collect();ids.sort();seen=ids.into_iter().rev().take(500).collect();}util::set_setting("supportSeenTrades",json!(seen.iter().collect::<Vec<_>>()));let _=app.emit("support",json!({"status":status,"alarm":down}));},Err(error)=>{let _=app.emit("support",json!({"error":error}));}}for _ in 0..90{if WATCH.load(SeqCst)!=generation{return;}tokio::time::sleep(std::time::Duration::from_secs(1)).await;}}});}
